export function trustLocale(locale: string): TrustLocale { return locale === "en" || locale === "pt" ? locale : "nb"; }
export function translated(locale: string, value: Translated): string {
  return value[trustLocale(locale) === "nb" ? 0 : trustLocale(locale) === "en" ? 1 : 2];
}
export function sectionText(locale: string, source: readonly SectionSource[]): TextSection[] {
  return source.map(section => ({ id: section.id, title: translated(locale, section.title), body: translated(locale, section.body), points: (section.points ?? []).map(point => translated(locale, point)) }));
}
export function revisionLabel(locale: string): string {
  const date = new Intl.DateTimeFormat(trustLocale(locale), { dateStyle: "long", timeZone: "UTC" }).format(new Date(`${TRUST_REVISION.updated}T12:00:00Z`));
  const version = TRUST_REVISION.version;
  return translated(locale, [`Arbeidsutkast v${version}. Innhold revidert: ${date}.`, `Review draft v${version}. Content revised: ${date}.`, `Rascunho para análise v${version}. Conteúdo revisto: ${date}.`]);
}

